\label{thm:stephen}
Let  $S$ and  $X$ be as above, and let $\sigma$ be the kernel of the natural epimorphism $(X\cup X^{-1})^{+}\rightarrow S$. For any  $w,v\in (X\cup X^{-1})^+$, we have:
\begin{enumerate}[leftmargin=8mm,itemsep=1mm,label=\textup{(\roman*)}]
    \item $\operatorname{\textit{S} \, \Gamma}(w\sigma)$  is inverse and deterministic;
    \item $w\sigma=v\sigma$ if and only if $w \in \textit{L}(\operatorname{\textit{S} \, \Gamma}(v\sigma))$ and $v \in \textit{L} (\operatorname{\textit{S} \, \Gamma}(w\sigma))$.
\end{enumerate}

When $-(x-1)p \leq qp \leq b-b_{\alpha} $ we have
\begin{align*}
    u\alpha^{-1} &= (-a, qp, b)(-(a_{\text{min}}+p), -p, b_{\alpha}-p)\\
    &=(-\max(a, a_{\text{min}}+p-qp), (q-1)p, \max(b, b_{\alpha}-p+qp))\\
    &=(-a, (q-1)p, b)\in R_{a,b},
\end{align*}
since $a=a_{\text{min}}+xp+r$;
whereas when $b-b_{\alpha} < qp \leq b$ we have:
\begin{align*}
    u\beta &= (-a, qp, b)(-a_{\beta}, -p, b_{\text{min}})\\
    &=(-\max(a, a_{\beta}-qp), (q-1)p, \max(b, b_{\text{min}}+qp))\\
    &=(-a, (q-1)p, b) \in R_{a,b}.
\end{align*}
The last equality follows from $a+b > a_{\beta}+b_{\alpha}$, which gives $qp > b-b_{\alpha} > -a+a_{\beta}$, and $b = b_{\text{min}}+yp+s$ and $q \leq y$. This completes the proof of Claim \ref{new_S_bar_claim_2}.

\label{thm:new_amlagam}
Let $S$ be a non-semilattice inverse subsemigroup of $FI_1$. 
Let $\operatorname{Inv} \langle X_E \mid R \rangle$ be any presentation for the semilattice $E(S)$ of the idempotents of $S$ in terms of the generating set
$X_E := \{x_e \colon e\in E(S)\}$ in one-one correspondence with $E(S)$. 
Also let $\operatorname{Inv} \langle Y \mid Q \rangle$ be a presentation for the subsemigoup $\overline{S}$ of $S$ generated by all the non-idempotent elements of $S$.
For each $e \in E(S) \cap \overline{S}$, let $w_e\in (Y\cup Y^{-1})^+$ be a word that represents $e$ in $\overline{S}$, and let 
\begin{align*}
    P := \{w_e = x_e \colon e \in E(S)\cap \overline{S}\}.
\end{align*}
Then, $S$ is defined by 
\begin{align}
    \operatorname{Inv} \langle X_E, Y \mid R, Q, P \rangle. \label{eq:new_amalgam_1}
\end{align}

\label{cor:new_conj}
Let $S$ be a non-semilattice inverse subsemigroup of $FI_1$. Suppose $A$ is a finite set of non-idempotents such that $S = \langle E(S), A \rangle$. Let $X_E := \{x_e\colon e\in E(S)\}$ and $Y_A := \{y_a \colon a \in A \}$ be sets in one-one correspondence with $E(S)$ and $A$, respectively. Suppose $E(S)$ is defined by $\operatorname{Inv} \langle X_E \mid R \rangle$. Define
\begin{align*}
    C := \{y_a^{-\epsilon} x_ey_a^\epsilon = x_{a^{-\epsilon}ea^\epsilon}  \colon a\in A,\, e\in E(S),\, \epsilon=\pm 1 \}.
\end{align*}
Then, there is a finite set $T$ of relations such that $S$ is defined by
\begin{align*}
    \operatorname{Inv} \langle X_E, Y_A \mid R, C, T \rangle.
\end{align*}

\label{prop:final}
Let $S$ be a non-semilattice inverse subsemigroup of $FI_1$, and let $\overline{S}$ be the inverse subsemigroup of $S$ generated by all non-idempotent elements of $S$. Then the following are
equivalent: \textup{(i)} $S$ is finitely generated; \textup{(ii)} $S$ is finitely presented;
\textup{(iii)} the set $S \setminus \overline{S}$ is finite.
